"use strict";
function setStep(i){const s=steps[i];document.querySelectorAll("[data-step]").forEach(b=>{const yes=Number(b.dataset.step)===i;b.classList.toggle("selected",yes);b.setAttribute("aria-pressed",String(yes))});const el=document.getElementById("step-detail");el.innerHTML=`<span class="pill">Paso ${i+1} · Pendiente de evidencia</span><h2>${s.title}</h2><div class="step-meta"><span>${s.when}</span><strong>${s.cost}</strong></div><h3>Qué hacemos</h3><p>${s.what}</p><h3>Por qué</h3><p>${s.why}</p><h3>Qué permite avanzar</h3><p>${s.done}</p>${refs(...s.ids)}`;el.classList.remove("swap");requestAnimationFrame(()=>el.classList.add("swap"))}
function setBudget(i){document.querySelectorAll("[data-budget]").forEach(b=>{const yes=Number(b.dataset.budget)===i;b.classList.toggle("selected",yes);b.setAttribute("aria-pressed",String(yes))});document.getElementById("budget-note").innerHTML=`<strong>${esc(D.budget[i].name)} · ${euro(D.budget[i].total)}</strong><p>${budgetNotes[i]}</p>`}
function showSection(id){const valid=["inicio","pasos","dinero","test","herramientas","equipo","fuentes"],target=document.getElementById(valid.includes(id)?id:"inicio");document.querySelectorAll(".view").forEach(el=>{el.hidden=el!==target;el.classList.toggle("active",el===target)});document.querySelectorAll(".nav-link").forEach(el=>{const yes=el.hash==="#"+target.id;el.classList.toggle("active",yes);if(yes)el.setAttribute("aria-current","page");else el.removeAttribute("aria-current")});document.title=({inicio:"Nuestra primera ronda",pasos:"El camino",dinero:"Cada euro cuenta",test:"Probemos un ejemplo",herramientas:"Qué necesitamos",equipo:"Equipo y decisiones",fuentes:"Fuentes y curso"}[target.id])+" | Aitor y Miguel"}
window.addEventListener("hashchange",()=>{showSection(location.hash.slice(1));window.scrollTo({top:0,behavior:"instant"})});
document.querySelectorAll(".view:not(#inicio)").forEach(s=>s.setAttribute("aria-labelledby",s.querySelector("h1").id));
document.querySelectorAll("form").forEach(f=>f.addEventListener("submit",e=>e.preventDefault()));
document.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;if(b.dataset.step!==undefined)setStep(Number(b.dataset.step));if(b.dataset.budget!==undefined)setBudget(Number(b.dataset.budget));if(b.dataset.ref)openReference(b.dataset.ref);if(b.dataset.preset)applyPreset(b.dataset.preset)});
const dialog=document.getElementById("reference-dialog");
function openReference(id){let body;if(id.startsWith("C")){const l=D.lessons.find(x=>x.id===id);if(!l)return;body=`<p class="eyebrow">TRANSCRIPCIÓN ORIGINAL · ${id}</p><h2 id="reference-title">${esc(l.title)}</h2><span class="pill">${esc(l.phase)}</span><h3>Aplicación en el piloto</h3><p>${esc(l.decision)}</p>${id==="C33"?'<blockquote>“si el producto lleva gastado €10 y el CPC es de más de €1, apagamos.”<cite>C33 · 00:21–00:26</cite></blockquote><p>Más de 20 € sin carritos: 00:26–00:34. Corte a 30–40 €: 00:35–01:08. Continuidad de 48 h bajo condiciones: 01:11–01:37.</p>':""}<p class="fine">Resumen de la hoja de ruta v3. La transcripción completa está en el proyecto y no se publica aquí.</p><a href="documentos/Hoja_ruta_ARZ_Urus_1500_EUR.pdf" target="_blank" rel="noopener">Abrir manual y mapa del curso</a>`}else{const s=D.sources.find(x=>x.id===id);if(!s)return;body=`<p class="eyebrow">FUENTE OFICIAL · ${id}</p><h2 id="reference-title">${esc(s.title)}</h2><p>${esc(s.summary)}</p><p class="fine">Consulta: ${s.checked}. Confirmar total y condiciones de la cuenta antes de contratar.</p><a class="button" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Abrir fuente oficial</a>`}document.getElementById("reference-body").innerHTML=body;dialog.showModal()}
dialog.querySelector(".dialog-close").addEventListener("click",()=>dialog.close());dialog.addEventListener("click",e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function updateCapacity(){const args={saving:Number(document.getElementById("tool-saving").value),extraAdmin:Number(document.getElementById("admin-extra").value),tax:Number(document.getElementById("ad-tax").value),filterCost:Number(document.getElementById("filter-cost").value)},r=M.capacity(args);document.getElementById("filter-output").value=euro(args.filterCost);document.getElementById("saving-output").value=euro(args.saving);document.getElementById("admin-output").value=euro(args.extraAdmin);document.getElementById("capacity-count").textContent=r.count;document.getElementById("capacity-breakdown").innerHTML=`<dl class="result-lines"><div><dt>Anuncios en el escenario</dt><dd>${euro(r.ads)}</dd></div><div><dt>Calentamiento + continuidad</dt><dd>150 € protegidos</dd></div><div><dt>Filtros, con recargos</dt><dd>${euro(r.filters)}</dd></div><div><dt>Medios, sin recargo</dt><dd>${euro(r.media)}</dd></div><div><dt>Capital total</dt><dd>1.500 €</dd></div></dl>${!r.funded?'<p class="error">No financia calentamiento y continuidad. Habría que replantear el piloto; este escenario no es ejecutable.</p>':""}`;return r}
document.getElementById("capacity-form").addEventListener("input",updateCapacity);document.getElementById("reset-capacity").addEventListener("click",()=>{document.getElementById("capacity-form").reset();updateCapacity()});
const numeric=id=>Number(document.getElementById(id).value),checked=id=>document.getElementById(id).checked;
function testArgs(){return {spend:numeric("test-spend"),clicks:numeric("test-clicks"),atc:numeric("test-atc"),purchases:numeric("test-purchases"),measured:checked("test-measured"),funded:checked("test-funded"),extended:checked("test-extended"),after48:checked("test-after48"),positive:checked("test-positive")}}
function updateTest(){document.getElementById("positive-row").hidden=!checked("test-after48");const el=document.getElementById("test-result"),form=document.getElementById("test-form");if(!form.checkValidity()||["test-spend","test-clicks","test-atc","test-purchases"].some(id=>document.getElementById(id).value==="")){el.innerHTML='<p class="error">Completa los campos con cifras válidas.</p>';return}try{const r=M.test(testArgs());el.dataset.state=r.key;el.innerHTML=`<span class="pill ${r.key==="stop"?"orange":r.key==="continue"?"green":"blue"}">${r.key==="stop"?"Corte":r.key==="continue"?"Continuidad condicionada":"Revisión"}</span><h2>${r.title}</h2><p>${r.reason}</p><dl class="result-lines"><div><dt>CPC del enlace</dt><dd>${r.cpc===null?"Sin clics":euro(r.cpc)}</dd></div><div><dt>Carritos / clics</dt><dd>${r.rate===null?"No calculable":number(r.rate)+"%"}</dd></div></dl><p class="fine">Ejemplo educativo. No crea, paga, pausa ni modifica campañas.</p>`;return r}catch(e){el.innerHTML=`<p class="error">${esc(e.message)}</p>`}}
document.getElementById("test-form").addEventListener("input",updateTest);
const presets={expensive:[10,5,0,0,true],"no-cart":[20.01,40,0,0,true],"no-sale":[30,50,4,0,true],good:[30,60,4,1,true],broken:[30,60,0,0,false]};
function applyPreset(key){const p=presets[key];if(!p)return;document.getElementById("test-form").reset();["test-spend","test-clicks","test-atc","test-purchases"].forEach((id,i)=>document.getElementById(id).value=p[i]);document.getElementById("test-measured").checked=p[4];updateTest()}
function updateMargin(){const el=document.getElementById("margin-result"),form=document.getElementById("margin-form");if(!form.checkValidity()||Array.from(form.querySelectorAll("input")).some(i=>i.value==="")){el.innerHTML='<p class="error">Completa los costes con cifras válidas.</p>';return}try{const r=M.economics(Object.fromEntries(["price","product","shipping","cpa","incidents","vat"].map(id=>[id,numeric(id)])));el.innerHTML=`<p class="eyebrow">ESTE PEDIDO DEJA</p><strong class="big-result ${r.contribution<0?"negative":""}">${euro(r.contribution)}</strong><p>Contribución tras costes variables y anuncios.</p><dl class="result-lines"><div><dt>Venta sin IVA del ejemplo</dt><dd>${euro(r.net)}</dd></div><div><dt>Comisión de pago</dt><dd>${euro(r.fee)}</dd></div><div><dt>Máximo de anuncios por compra antes de fijos</dt><dd>${euro(r.before)}</dd></div><div><dt>ROAS de equilibrio antes de fijos</dt><dd>${r.breakRoas===null?"Sin margen positivo":number(r.breakRoas)}</dd></div><div><dt>ROAS del ejemplo</dt><dd>${r.roas===null?"Sin gasto":number(r.roas)}</dd></div></dl><p class="fine">${r.contribution>0?"Positivo antes de fijos. Faltan herramientas, administración y ajustes reales de incidencias/impuestos del negocio.":"No deja contribución positiva; gastar más no arregla este margen por sí solo."} No es una previsión.</p>`;return r}catch(e){el.innerHTML=`<p class="error">${esc(e.message)}</p>`}}
document.getElementById("margin-form").addEventListener("input",updateMargin);
document.getElementById("start-date").addEventListener("input",e=>{const val=e.target.value,el=document.getElementById("calendar-result");if(!val){el.innerHTML="<p>Sin fecha de inicio confirmada.</p>";return}const start=new Date(val+"T12:00:00");if(Number.isNaN(start.getTime()))return;const date=n=>{const d=new Date(start);d.setDate(d.getDate()+n);return new Intl.DateTimeFormat("es-ES",{day:"numeric",month:"short",year:"numeric"}).format(d)};el.innerHTML=[["Primera prueba",15,20],["Tramo 2, por hito",17,25],["Tramo 3, por hito",25,40],["Revisión completa",45,60]].map(([t,a,b])=>`<div><strong>${t}</strong><span>${date(a)} – ${date(b)}</span></div>`).join("")});
const questions=[{q:"¿Los 150 € pendientes de Shopify se pueden gastar hoy?",options:["Sí, una venta ya es dinero disponible.","No, primero debe llegar el ingreso."],correct:1,why:"Los cobros pendientes no pagan al proveedor hoy. Se separan de la caja disponible."},{q:"Una prueba hizo una venta. ¿Ya tenemos un ganador?",options:["Sí, cualquier venta valida el producto.","No, revisamos costes, señales, entregas y continuidad."],correct:1,why:"Una compra es una señal. Falta saber si se repite con contribución y caja suficientes."},{q:"¿Qué activa el siguiente tramo de 500 €?",options:["Que pasen exactamente cinco días.","Informe, trabajo concreto y decisión acordada."],correct:1,why:"Los tramos siguen hitos y caja. No son automáticos ni exigen un ganador."}];
document.getElementById("quiz-content").innerHTML=questions.map((q,i)=>`<fieldset><legend>${i+1}. ${q.q}</legend><div class="quiz-options">${q.options.map((s,j)=>`<button type="button" class="button ghost" data-question="${i}" data-answer="${j}">${s}</button>`).join("")}</div><p id="quiz-${i}" class="quiz-feedback" aria-live="polite"></p></fieldset>`).join("");
document.getElementById("quiz-content").addEventListener("click",e=>{const b=e.target.closest("[data-question]");if(!b)return;const i=Number(b.dataset.question),q=questions[i],yes=Number(b.dataset.answer)===q.correct;document.getElementById("quiz-"+i).textContent=(yes?"Correcto. ":"Revisa esta idea: ")+q.why;b.parentElement.querySelectorAll("button").forEach(x=>x.setAttribute("aria-pressed",String(x===b)))});
function filterSources(){const term=document.getElementById("source-search").value.trim().toLocaleLowerCase("es");let count=0;document.querySelectorAll(".searchable").forEach(el=>{const yes=el.dataset.search.includes(term);el.hidden=!yes;if(yes)count++});document.getElementById("search-count").textContent=count+" referencias visibles de 90 (58 lecciones + 32 fuentes)."}
document.getElementById("source-search").addEventListener("input",filterSources);
setStep(0);setBudget(6);updateCapacity();updateTest();updateMargin();filterSources();showSection(location.hash.slice(1)||"inicio");
